   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Experiment
    */
	public Experiment createExperiment( CreateExperimentCommand command )
    throws ProcessingException, IllegalArgumentException {

		Experiment entity = new Experiment();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	ExperimentValidator.getInstance().validate( command );    

            entity.setExperimentId( command.getExperimentId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setStatus( command.getStatus() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of Experiment {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Experiment - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateExperimentCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Experiment
    */
    public Experiment updateExperiment( UpdateExperimentCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Experiment entity = new Experiment();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	ExperimentValidator.getInstance().validate( command );    

            entity.setExperimentId( command.getExperimentId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setTrainingRuns( command.getTrainingRuns() );
            entity.setModels( command.getModels() );
            entity.setNotebooks( command.getNotebooks() );
            entity.setStatus( command.getStatus() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.log( Level.INFO, "done saving of Experiment {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Experiment - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
   /**
    * Deletes the associatied value object
    * @param		command DeleteExperimentCommand
    * @exception 	ProcessingException
    */
    public void delete( DeleteExperimentCommand command ) 
    throws ProcessingException, IllegalArgumentException {	
        UUID id = null;
        
    	try {  
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	ExperimentValidator.getInstance().validate( command );    
        
        	id = command.getExperimentId();
        	
        	// ------------------------------------------
        	// delete the entity
        	// ------------------------------------------
        	projector.delete(id);

        	LOGGER.log( Level.INFO, "done deleting of Experiment {0} ", id );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to delete Experiment using Id = "  + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }
    }

    /**
     * Method to retrieve the Experiment via ExperimentFetchOneSummary
     * @param 	summary ExperimentFetchOneSummary 
     * @return 	ExperimentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Experiment getExperiment( ExperimentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ExperimentFetchOneSummary arg cannot be null" );
    	
    	Experiment entity = null;
    	UUID id = summary.getExperimentId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	ExperimentValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a Experiment using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Experiment with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Experiments
     *
     * @return 	List<Experiment> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Experiment> getAllExperiment() 
    throws ProcessingException {
        List<Experiment> list = null;

        try {        	
        	list = projector.findAll( new FindAllExperimentQuery() );
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Experiment";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Workspace on Experiment
     * @param		command AssignWorkspaceToExperimentCommand	
     * @exception	ProcessingException
     */     
	public void assignWorkspace( AssignWorkspaceToExperimentCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ExperimentValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignWorkspace(command.getExperimentId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AnalyticsWorkspace using id " + command.getExperimentId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

    /**
     * unAssign Workspace on Experiment
     * @param		command UnAssignWorkspaceFromExperimentCommand
     * @exception	ProcessingException
     */     
	public void unAssignWorkspace( UnAssignWorkspaceFromExperimentCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	ExperimentValidator.getInstance().validate( command );    
	
	    	// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.unAssignWorkspace(command.getExperimentId());
		}
		catch( Exception exc ) {
			final String msg = "Failed to unassign Workspace on Experiment";
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}
	}
	

